package com.xinyi.rongli.payment.service;
import com.fasterxml.jackson.databind.JsonNode;
import com.xinyi.rongli.integration.domain.*;
import com.xinyi.rongli.integration.mapper.IntegrationMapper;
import com.xinyi.rongli.integration.service.*;
import com.xinyi.rongli.payment.mapper.PaymentMapper;
import com.xinyi.rongli.payment.domain.PaymentTransaction;
import com.xinyi.rongli.platform.json.ViJson;
import com.xinyi.rongli.platform.error.*;
import com.wechat.pay.java.core.*;
import org.springframework.stereotype.Service;
import java.util.*;
import java.nio.charset.StandardCharsets;
@Service
public class PaymentConfiguration {
 private final PaymentMapper payments;private final IntegrationMapper mapper;private final IntegrationSecrets secrets;private final IntegrationValidation validation;private final IntegrationAuthority authority;
 public PaymentConfiguration(PaymentMapper payments,IntegrationMapper mapper,IntegrationSecrets secrets,IntegrationValidation validation,IntegrationAuthority authority){this.payments=payments;this.mapper=mapper;this.secrets=secrets;this.validation=validation;this.authority=authority;}
 public record Policy(IntegrationProfile profile,IntegrationRevision revision,JsonNode config){}
 public Policy policy(PaymentTransaction payment){var p=payments.policyProfile(payment.getPolicyRevisionId());active(p,payment.getReceiverDeptId(),"PAYMENT_POLICY");var r=mapper.revision(p.getId(),p.getActiveRevisionId());return new Policy(p,r,ViJson.tree(r.getConfigJson()));}
 private void active(IntegrationProfile p,long owner,String kind){if(p==null||!kind.equals(p.getKind())||p.getOwnerDeptId()!=owner||!authority.environment.equals(p.getEnvironment())||!"ACTIVE".equals(p.getLifecycle())||p.getActiveRevisionId()==null||mapper.wasPublished(p.getId(),p.getActiveRevisionId())==0)invalid();}
 public IntegrationProfile newMerchant(Policy policy,String accountApp){if(!policy.config().path("wechatEnabled").asBoolean())throw new ViException(ViErrorCode.VI_PAYMENT_METHOD_DISABLED);if(!validation.validate(policy.profile(),policy.revision()).passed())invalid();var ref=policy.config().path("wechatMerchant");var p=mapper.profile(ref.path("profileId").asLong());active(p,policy.profile().getOwnerDeptId(),"WECHAT_PAY");if(p.getActiveRevisionId()!=ref.path("revisionId").asLong())invalid();var c=ViJson.tree(mapper.revision(p.getId(),p.getActiveRevisionId()).getConfigJson());var appRef=c.path("appProfile");var app=mapper.profile(appRef.path("profileId").asLong());active(app,p.getOwnerDeptId(),"WECHAT_APP");var a=ViJson.tree(mapper.revision(app.getId(),app.getActiveRevisionId()).getConfigJson());if(!accountApp.equals(a.path("appId").asText())||!a.path("enabled").asBoolean())invalid();return p;}
 public String mchid(IntegrationProfile p){return ViJson.tree(mapper.revision(p.getId(),p.getActiveRevisionId()).getConfigJson()).path("mchid").asText();}
 public Config sdk(PaymentTransaction pay){var p=mapper.profile(pay.getMerchantProfileId());active(p,pay.getReceiverDeptId(),"WECHAT_PAY");var r=mapper.revision(p.getId(),p.getActiveRevisionId());var c=ViJson.tree(r.getConfigJson());var original=mapper.revision(p.getId(),pay.getMerchantRevisionId());if(original==null||!pay.getMchid().equals(c.path("mchid").asText())||!ViJson.tree(original.getConfigJson()).path("appProfile").path("profileId").equals(c.path("appProfile").path("profileId")))invalid();var app=mapper.profile(c.path("appProfile").path("profileId").asLong());active(app,pay.getReceiverDeptId(),"WECHAT_APP");if(!pay.getAppId().equals(ViJson.tree(mapper.revision(app.getId(),app.getActiveRevisionId()).getConfigJson()).path("appId").asText()))invalid();
  byte[] key=secrets.read(p,r,"merchantPrivateKey"),api=null;try{api=secrets.read(p,r,"apiV3Key");String pem=new String(key,StandardCharsets.UTF_8);if("WECHATPAY_PUBLIC_KEY".equals(c.path("verificationMode").asText()))return new RSAPublicKeyConfig.Builder().merchantId(pay.getMchid()).merchantSerialNumber(c.path("merchantCertificateSerial").asText()).privateKey(pem).apiV3Key(new String(api,StandardCharsets.UTF_8)).publicKeyId(c.path("wechatPayPublicKeyId").asText()).publicKey(c.path("wechatPayPublicKeyPem").asText()).build();if(!"PLATFORM_CERT".equals(c.path("verificationMode").asText()))invalid();var certificates=new ArrayList<String>();for(var cert:c.path("platformCertificates"))certificates.add(cert.path("pem").asText());if(certificates.isEmpty())invalid();return new RSAConfig.Builder().merchantId(pay.getMchid()).merchantSerialNumber(c.path("merchantCertificateSerial").asText()).privateKey(pem).wechatPayCertificates(certificates.toArray(String[]::new)).build();}catch(ViException e){throw e;}catch(RuntimeException e){throw new ViException(ViErrorCode.VI_CONFIG_INVALID,"支付签名及验签配置无效");}finally{Arrays.fill(key,(byte)0);if(api!=null)Arrays.fill(api,(byte)0);}
 }
 public Map<String,Object> offline(Policy policy,boolean allowed){var c=policy.config();var m=new LinkedHashMap<String,Object>();m.put("method","OFFLINE");m.put("label","企业线下支付");m.put("available",allowed&&c.path("offlineEnabled").asBoolean());for(String key:List.of("offlineInstructions","offlineReceiverName","offlineBankName","offlineAccountName","offlineContactName","offlineContactPhone")){String target=switch(key){case "offlineInstructions"->"instructions";case "offlineReceiverName"->"receiverName";case "offlineBankName"->"bankName";case "offlineAccountName"->"bankAccountName";case "offlineContactName"->"contactName";default->"contactPhone";};if(c.hasNonNull(key))m.put(target,c.path(key).asText());}if(c.has("offlineMethods"))m.put("offlineMethods",ViJson.read(c.path("offlineMethods").toString(),List.class));return m;}
 private static void invalid(){throw new ViException(ViErrorCode.VI_CONFIG_INVALID,"收款配置与订单主体或应用不一致");}
}
